const input = $input.first().json;
const fields = input.fields || {};
const sanitize = (s, max) => String(s ?? '')
  .normalize('NFKC')
  .replace(/[\u200B-\u200F\u202A-\u202E\u2060-\u2064\uFEFF]/g, '')
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
  .replace(/<\/?untrusted_input[^>]*>/gi, '')
  .replace(/<[^>]*>/g, '')
  .trim()
  .slice(0, max || 5000);
const PATTERNS = [
  ['override', /ignore (all |any )?(of )?(the |your )?(previous|prior|above|earlier) (instructions|rules|prompts?)/i],
  ['override', /disregard (the |your |all )?(system|previous|prior) (prompt|instructions|rules)/i],
  ['override', /ignore (your|the) (rules|instructions|system prompt)/i],
  ['role_hijack', /\byou are now\b|\bact as (an?|the) (admin|administrator|system|hr manager)/i],
  ['prompt_leak', /(reveal|print|show|repeat) (me )?(your|the) (system )?(prompt|instructions)/i],
  ['score_manipulation', /(rank|score|rate|mark) (me|this candidate|this answer)( as)? (#?1|first|highest|perfect|10\s*\/\s*10)/i],
  ['fake_markup', /\[INST\]|<\|?(system|im_start)\|?>|BEGIN (SYSTEM|ADMIN)/i],
  ['action_request', /(send|forward|email) (this|all|the) .{0,30}(to |@)/i]
];
const clean = {};
const flags = [];
for (const [name, text] of Object.entries(fields)) {
  const raw = String(text ?? '');
  clean[name] = sanitize(raw, 5000);
  for (const [type, re] of PATTERNS) {
    if (re.test(raw) || re.test(clean[name])) flags.push({ field: name, type });
  }
}
return [{ json: { clean, flags, injection_suspected: flags.length > 0 } }];
